begin;
-- Add bounded content layout choices; existing stored preferences and grants are preserved.
create or replace function sill_private.validate_workspace_preferences(v jsonb)
returns void language sql immutable security invoker set search_path='' as $$
  select sill_private.validate_schema(v, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"cardTextSize":{"type":"string","enum":["small","standard","large"]},"cardSpacing":{"type":"string","enum":["compact","standard","roomy"]},"cardPadding":{"type":"string","enum":["compact","standard","roomy"]},"readerTextSize":{"type":"string","enum":["small","standard","large"]},"readerSpacing":{"type":"string","enum":["compact","standard","roomy"]},"readerWidth":{"type":"string","enum":["narrow","standard","full"]},"textWeight":{"type":"string","enum":["standard","strong"]},"singleKeyShortcuts":{"type":"boolean"},"reduceMotion":{"type":"boolean"},"reduceTransparency":{"type":"boolean"},"sort":{"type":"string","enum":["priority","unread","time"]},"stack":{"type":"boolean"},"fadeRead":{"type":"boolean"},"archiveAfter":{"type":"string","enum":["3d","7d","never"]},"floatTimely":{"type":"boolean"},"collapseOnFinish":{"type":"boolean"},"newHint":{"type":"string","enum":["away","off"]},"theme":{"type":"string","enum":["system","light","dark"]},"density":{"type":"string","enum":["compact","standard","roomy"]},"aiLocal":{"type":"boolean"},"onboarded":{"type":"boolean"},"hiddenActions":{"maxItems":9,"type":"array","items":{"type":"string","enum":["bookmark","tag","later","reply","open","join","snooze","download","dismiss"]}}},"additionalProperties":false}'::jsonb)
$$;
commit;
